import{validateReport,departure,demoReport,signalNames}from'./model.js';
import eShopReport from './eshop-report.js';
const $=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),pct=x=>(x*100).toLocaleString('en-US',{maximumFractionDigits:1})+'%',num=x=>x.toLocaleString('en-US'),badge=r=>`<span class="badge ${r}">${r}</span>`;
let report=eShopReport,selected=report.components[0].component,activePerson=null;
const people=()=>[...new Map(report.components.flatMap(c=>c.contributors.map(p=>[p.contributor,p.name]))).entries()].sort((a,b)=>a[1].localeCompare(b[1],'en'));
function render(){
 $('revision').textContent='REV '+report.revision.slice(0,12);$('reference').textContent=new Date(report.as_of).toLocaleDateString('en-US')+' · reference date';
 const metrics=[['Components',report.components.length,'Directory-based scope'],['Contributors',people().length,'With historical evidence'],['Critical continuity risk',report.components.filter(c=>c.risk==='CRITICAL').length,'Evidence concentration ≥ 0.80'],['Commits',report.commit_count,'Original Git history']];
 $('metrics').innerHTML=metrics.map(([l,v,n],i)=>`<article class="metric ${i===2?'critical':''}"><div class="label">${l}</div><div class="value">${num(v)}</div><div class="note">${n}</div></article>`).join('');
 const previous=$('person').value;$('person').innerHTML=people().map(([id,name])=>`<option value="${esc(id)}">${esc(name)} · ${esc(id)}</option>`).join('');if(people().some(([id])=>id===previous))$('person').value=previous;
 const f=report.filters||{},e=report.filter_evidence;$('scope').textContent=`Scope: ${report.components.length} components. Shallow clone: ${report.shallow?'yes — history is incomplete':'no'}. Bot filter: ${f.exclude_bots?'enabled':'disabled'}. Generated-file filter: ${f.exclude_generated?'enabled':'disabled'}. `+(e?`Excluded file changes: ${e.excluded_file_changes} / ${e.input_file_changes}. `:'')+`Path patterns: ${(f.paths||[]).join(', ')||'none'}. Author patterns: ${(f.authors||[]).join(', ')||'none'}.`;
 renderOverview();renderComponents();renderContributors();renderEvidence();renderStress();
}
function renderOverview(){const risks=['LOW','MEDIUM','HIGH','CRITICAL'];$('overview-content').innerHTML=`<article class="panel summary"><p class="eyebrow">OVERVIEW</p><h2>Continuity evidence at a glance</h2><p class="muted">The report describes historical Git activity concentration. It is an evidence proxy, not a measure of people.</p><div class="risk-grid">${risks.map(r=>`<div><span>${r}</span><strong>${report.components.filter(c=>c.risk===r).length}</strong></div>`).join('')}</div></article><article class="panel summary"><p class="eyebrow">START EXPLORING</p><h2>Follow the evidence</h2><ol><li>Review concentration by component.</li><li>Inspect contributor and file evidence.</li><li>Apply a continuity stress-test scenario.</li></ol></article>`;}
function renderComponents(){const q=$('search').value.toLocaleLowerCase('en'),risk=$('risk').value,cs=report.components.filter(c=>(!risk||c.risk===risk)&&c.component.toLocaleLowerCase('en').includes(q)).sort((a,b)=>b.concentration-a.concentration||a.component.localeCompare(b.component,'en'));if(!cs.some(c=>c.component===selected)){selected=cs[0]?.component;activePerson=null;}$('visible-count').textContent=cs.length+' / '+report.components.length;$('empty').hidden=!!cs.length;$('component-rows').innerHTML=cs.map(c=>`<tr class="${selected===c.component?'selected':''}"><td><button class="component-link" data-component="${esc(c.component)}" aria-pressed="${selected===c.component}">${esc(c.component)}</button></td><td>${badge(c.risk)}</td><td>${c.concentration.toFixed(3)}<div class="bar"><span style="width:${c.concentration*100}%"></span></div></td><td>${c.contributors.length}</td></tr>`).join('');renderDetail();}
function renderDetail(){const c=report.components.find(c=>c.component===selected);if(!c){$('detail').innerHTML='<h2>Component selection</h2><p class="muted">There are no components to display in this view.</p>';return;}const ps=[...c.contributors].sort((a,b)=>b.share-a.share),p=ps.find(p=>p.contributor===activePerson)||ps[0];activePerson=p.contributor;$('detail').innerHTML=`<div class="detail-top"><p class="eyebrow">COMPONENT DETAIL</p>${badge(c.risk)}</div><h2>${esc(c.component)}</h2><p class="muted">${ps.length} contributors · ${new Set(ps.flatMap(p=>p.files)).size} historical files</p><h3>Contribution shares</h3>${ps.map(p=>`<div class="contributor"><button data-contributor="${esc(p.contributor)}">${esc(p.name)}<small>${esc(p.contributor)}</small></button><strong>${pct(p.share)}</strong></div>`).join('')}<div class="signals"><h3>${esc(p.name)} · score evidence</h3><p class="muted">Raw score ${p.score.toFixed(3)} · ${p.commits} commits · ${p.files.length} files</p>${Object.entries(signalNames).map(([key,name])=>`<div class="signal"><span>${name}</span><div class="bar"><span style="width:${p.signals[key]*100}%"></span></div><span>${p.signals[key].toFixed(2)}</span></div>`).join('')}</div><details class="evidence"><summary>File evidence (${p.files.length})</summary><ul>${p.files.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></details>`;}
function renderContributors(){const a=new Map();for(const c of report.components)for(const p of c.contributors){const x=a.get(p.contributor)||{...p,components:new Set(),files:new Set(),score:0};x.components.add(c.component);p.files.forEach(f=>x.files.add(f));x.score+=p.score;a.set(p.contributor,x);}const rows=[...a.values()].sort((a,b)=>b.components.size-a.components.size||a.name.localeCompare(b.name,'en'));$('contributor-rows').innerHTML=rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.contributor)}</small></td><td>${p.components.size}</td><td>${p.files.size}</td><td>${p.score.toFixed(3)} aggregate score</td></tr>`).join('');}
function renderEvidence(){$('evidence-rows').innerHTML=[...report.components].sort((a,b)=>b.concentration-a.concentration).map(c=>`<tr><td>${esc(c.component)}</td><td>${badge(c.risk)}</td><td>${c.contributors.length}</td><td>${new Set(c.contributors.flatMap(p=>p.files)).size}</td><td>${c.concentration.toFixed(3)}</td></tr>`).join('');}
function renderStress(){const xs=departure(report,$('person').value);$('impact-summary').textContent=xs.length?`${xs.length} affected components · ${xs.filter(i=>!i.successor).length} components have no strong evidence overlap`:'No contributor scenario is available.';$('impact-rows').innerHTML=xs.map(i=>`<tr><td>${esc(i.component)}</td><td><strong>${pct(i.loss)}</strong><div class="bar"><span style="width:${i.loss*100}%"></span></div></td><td>${i.successor?esc(i.successor.name):'No strong evidence overlap found'}</td><td>${i.successor?`${pct(i.successor.overlap)} historical file overlap`:'—'}</td><td><details><summary>${i.uncovered.length} coverage gaps · ${i.remaining.length} remaining contributors</summary><p>${i.uncovered.map(esc).join('<br>')||'No coverage gaps.'}</p></details></td></tr>`).join('');}
function setView(next){for(const name of ['overview','components','contributors','evidence','stress']){$(name).hidden=name!==next;$(name+'-tab').classList.toggle('active',name===next);$(name+'-tab').setAttribute('aria-pressed',String(name===next));}}
for(const n of ['overview','components','contributors','evidence','stress'])$(n+'-tab').onclick=()=>setView(n);$('search').oninput=renderComponents;$('risk').onchange=renderComponents;$('person').onchange=renderStress;$('component-rows').onclick=e=>{const b=e.target.closest('[data-component]');if(b){selected=b.dataset.component;activePerson=null;renderComponents();}};$('detail').onclick=e=>{const b=e.target.closest('[data-contributor]');if(b){activePerson=b.dataset.contributor;renderDetail();}};
function load(data,name,sample=false,type='LOCAL JSON'){report=validateReport(data);selected=report.components[0]?.component;activePerson=null;$('search').value='';$('risk').value='';$('source-name').textContent=name;$('source-type').textContent=sample?'STATIC GIT SAMPLE':type;$('message').textContent=report.shallow?'This report was created from a shallow clone; incomplete history can affect the results.':'';render();}
$('demo').onclick=()=>load(eShopReport(),'dotnet/eShop · validation sample',true);$('upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('The file exceeds the 30 MB limit. Select a smaller report.');load(JSON.parse(await file.text()),file.name);}catch(error){$('message').textContent=error instanceof SyntaxError?'The JSON could not be read. Confirm that the file contains valid JSON.':error.message;}finally{e.target.value='';}};
for(const label of document.querySelectorAll('label[for="upload"]'))label.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();$('upload').click();}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='continuity-report.json';link.click();URL.revokeObjectURL(link.href);};
async function runAnalysis(input,button,type,empty){const repository=$(input).value.trim();if(!repository){$('message').textContent=empty;return;}const b=$(button);b.disabled=true;b.textContent='Analyzing…';try{const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({repository})}),data=await response.json();if(!response.ok)throw Error(data.error||'Analysis failed.');load(data,repository,false,type);}catch(error){$('message').textContent=error instanceof Error?error.message:'Analysis failed.';}finally{b.disabled=false;b.textContent=button==='run-clone-analysis'?'Clone and analyze':'Analyze path';}}
async function checkLocalExplorer(){if(!['127.0.0.1','localhost','::1'].includes(location.hostname))return;try{if(!(await fetch('/api/health')).ok)throw Error();$('local-explorer').hidden=false;$('hosted-instructions').hidden=true;$('run-local-analysis').onclick=()=>runAnalysis('repository-path','run-local-analysis','LOCAL GIT','Enter a local Git repository path.');$('run-clone-analysis').onclick=()=>runAnalysis('clone-url','run-clone-analysis','REMOTE GIT','Enter a public HTTPS clone URL.');const response=await fetch('/api/report');if(response.ok)load(await response.json(),'Initial repository analysis',false,'LOCAL EXPLORER');}catch{/* static demo needs no explorer */}}
checkLocalExplorer();render();
